def calc(a, op, b):
    if op == "+":
        return a + b
    elif op == "*":
        return a * b
    return "Неизвестная операция"


print(calc(6, "*", 7))
print(calc(2, "^", 3))

def divide(a, b):
    try:
        return a / b
    except ZeroDivisionError:
        return "На ноль делить нельзя"


print(divide(10, 4))
print(divide(5, 0))
